export function buildAll() {
  let total = 0;
  for (const c of CFG) {
    const g = GRAM[c.key];
    total += build({
      id: c.id, section: 'practical-scenarios', level: c.level, minutes: c.minutes,
      title: c.title, titleAr: c.titleAr,
      objectives: [`Handle real situations: ${c.title.toLowerCase()}`, 'Listen and type practical service lines', 'Build confident phrases for travel and work'],
      grammar: g,
      vocabulary: VOC[c.key],
      pools: c.pools,
    });
  }
  return { section: 'practical-scenarios', lessons: CFG.length, exercises: total };
}




